59| /** Replace the `status:` scalar value in a frontmatter, preserving every other byte. `fromStatus`, when
60|  *  set, makes the patch apply ONLY when the current status line equals that value (whitespace-tolerant) —
61|  *  otherwise the frontmatter is returned UNCHANGED with `replaced:false` (a no-op, NOT an error: callers
62|  *  that already judged "is it <fromStatus>" via the develop ref use this to avoid clobbering a
63|  *  concurrently-flipped disk, see setTaskStatus). No `status:` line ⇒ fail-closed (ok:false). */
64| export function patchStatusField(
65|   frontmatterRaw: string,
66|   toStatus: string,
67|   fromStatus?: string,
68| ): { ok: true; fm: string; from: string; replaced: boolean; to: string } | { ok: false; reason: string } {
69|   const statusLineRe = /^status:[ \t]*[^\r\n]*$/m;
70|   const line = frontmatterRaw.match(statusLineRe);
71|   if (!line) return { ok: false, reason: "no-status-line" };
72|   const from = line[0].replace(/^status:[ \t]*/, "").trim();
73|   if (fromStatus !== undefined && from !== fromStatus) {
74|     return { ok: true, fm: frontmatterRaw, from, replaced: false, to: toStatus };
75|   }
76|   return { ok: true, fm: frontmatterRaw.replace(statusLineRe, `status: ${toStatus}`), from, replaced: true, to: toStatus };
77| }
